var verifyPreorder = function(preorder) {
    const stack = [];
    let low = -Infinity;
    for (const x of preorder) {
        if (x < low) return false;
        while (stack.length > 0 && x > stack[stack.length - 1]) {
            low = stack.pop();
        }
        stack.push(x);
    }
    return true;
};
